WITH ship_mode_stats AS (SELECT sm.sm_type, COUNT(*) AS sales_count, AVG(ws.ws_net_profit) AS avg_profit FROM web_sales ws JOIN ship_mode sm ON ws.ws_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY sm.sm_type HAVING COUNT(*) > 1000) SELECT sm_type, sales_count, avg_profit, CASE WHEN avg_profit > 50000 THEN 'Profitable' ELSE 'Less Profitable' END AS profitability FROM ship_mode_stats ORDER BY avg_profit DESC
